interface.definition:
a!localVariables(
  /* Get ASSIGNED team roles */
  local!teamrole: if(
    a!isNotNullOrEmpty(ri!teamid),
    #"_a-0000eef8-4604-8000-9e54-011c48011c48_1138645"(teamid: ri!teamid, isActive: true()),
    {}
  ),

  local!groupid: if(
    a!isNotNullOrEmpty(local!teamrole),
    index(
      local!teamrole,
      #"urn:appian:record-field:v1:139cb21e-dd78-4694-a8ad-b43e2d51226f/da39fffc-c223-49f0-b99c-5a3a8f8ad3b8",
      {}
    ),
    {}
  ),

  local!groupcheck: if(
    a!isNotNullOrEmpty(local!groupid),
    local!groupid,
    {-1}
  ),

  /* Get UAM Application Role data for assigned groups */
  local!checkappgroup: if(
    a!isNotNullOrEmpty(local!groupid),  /* ← Only query if groupid exists */
    #"_a-0000eef8-4604-8000-9e54-011c48011c48_1136641"(
      groupno: local!groupcheck,
      isActive: true()
    ),
    {}
  ),

  /* Extract IDs and groupnos */
  local!groupids: if(
    a!isNotNullOrEmpty(local!checkappgroup),
    index(
      local!checkappgroup,
      #"urn:appian:record-field:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6/8dc81246-29c1-4324-803b-d2686f3304b2",
      {}
    ),
    {}
  ),

  local!allids: if(
    a!isNotNullOrEmpty(local!checkappgroup),
    index(
      local!checkappgroup,
      #"urn:appian:record-field:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6/e54fba8a-c899-4306-9f96-9474398e8fe0",
      {}
    ),
    {}
  ),

  local!selected: {},

  {
    /* Show grid only if there are assigned roles */
    if(
      a!isNotNullOrEmpty(local!groupid),
      #"SYSTEM_SYSRULES_gridField_v5"(
        label: "Team Assigned roles",
        labelPosition: "ABOVE",
        data: #"SYSTEM_SYSRULES_recordData"(
          recordType: #"urn:appian:record-type:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6",
          filters: {
            #"SYSTEM_SYSRULES_queryFilter"(
              field: #"urn:appian:record-field:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6/8dc81246-29c1-4324-803b-d2686f3304b2",
              operator: "in",
              value: local!groupcheck
            )
          }
        ),
        showRefreshButton: ri!refreshbutton,
        showSearchBox: ri!searchbox,
        selectable: ri!select,
        selectionValue: local!selected,
        selectionStyle: "ROW_HIGHLIGHT",
        selectionSaveInto: {
          local!selected,
          a!save(
            ri!selectedids,
            if(
              a!isNotNullOrEmpty(local!selected),
              index(
                local!groupids,
                wherecontains(tointeger(local!selected), local!allids),
                {}
              ),
              {}
            )
          )
        },
        columns: {
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Group Name",
            value: a!defaultValue(
              fv!row[#"urn:appian:record-field:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6/cd882668-a8b3-4169-90e0-07558bb8f81d/e8ca0cac-e7b4-4dfc-a87f-9c9f6e12a24c"],
              "–"
            ),
            sortField: #"urn:appian:record-field:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6/8dc81246-29c1-4324-803b-d2686f3304b2",
            align: "START"
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Group Role",
            value: a!defaultValue(
              fv!row[#"urn:appian:record-field:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6/cd882668-a8b3-4169-90e0-07558bb8f81d/4af96ff0-51ae-494e-b291-9b69501ced3f/299b80ba-6859-4a51-9327-066924ec76d4"],
              "–"
            ),
            sortField: #"urn:appian:record-field:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6/cd882668-a8b3-4169-90e0-07558bb8f81d/9e6a24a7-2da9-46e2-ade4-46002441f00a",
            align: "START"
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Created By",
            value: a!defaultValue(
              fv!row[#"urn:appian:record-field:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6/9beb3839-489c-4563-ace8-1b78b8bac4ee"],
              "–"
            ),
            sortField: #"urn:appian:record-field:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6/9beb3839-489c-4563-ace8-1b78b8bac4ee"
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Created On",
            value: if(
              isnull(
                fv!row[#"urn:appian:record-field:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6/fb609b13-57ee-4a22-b5cf-57e04069432e"]
              ),
              "–",
              datetext(
                fv!row[#"urn:appian:record-field:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6/fb609b13-57ee-4a22-b5cf-57e04069432e"],
                "default"
              )
            ),
            sortField: #"urn:appian:record-field:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6/fb609b13-57ee-4a22-b5cf-57e04069432e",
            align: "END",
            width: "NARROW_PLUS"
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Modified By",
            value: a!defaultValue(
              fv!row[#"urn:appian:record-field:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6/dd64c9ee-57b2-4c96-a1b5-af97a3ebb318"],
              "–"
            ),
            sortField: #"urn:appian:record-field:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6/dd64c9ee-57b2-4c96-a1b5-af97a3ebb318"
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Modified On",
            value: if(
              isnull(
                fv!row[#"urn:appian:record-field:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6/16369c2a-adbe-4ffc-9162-49a6413295ed"]
              ),
              "–",
              datetext(
                fv!row[#"urn:appian:record-field:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6/16369c2a-adbe-4ffc-9162-49a6413295ed"],
                "default"
              )
            ),
            sortField: #"urn:appian:record-field:v1:a54a3394-393d-4e6a-8737-0e73bb9b47e6/16369c2a-adbe-4ffc-9162-49a6413295ed",
            align: "END",
            width: "NARROW_PLUS"
          )
        },
        refreshAfter: "RECORD_ACTION",
        validations: {}
      ),
      /* Show message when no roles assigned */
      #"SYSTEM_SYSRULES_richTextDisplayField"(
        value: #"SYSTEM_SYSRULES_richTextItem_v1"(
          text: "No roles assigned to this team.",
          style: "EMPHASIS"
        )
      )
    )
  }
)
